applicability_rules.guard_fragment:
basic(Config) when is_list(Config) ->
    case os:type() of
        {unix, linux} ->
            do_basic(Config);
        {unix, sunos} ->
            do_basic(Config);
        {win32,_} ->
            do_basic(Config);
        _ ->
            {skipped, "Dynamic linking and erl_interface not fully examined"
                      " on this platform..."}

